import AVFoundation
import AppKit
import ScreenCaptureKit

/// `record_screen` — File ▸ New Recording… without the panel (road map 3,
/// R1d): `ScreenRecorder.shared`, the object the panel drives, run for a
/// fixed number of seconds from the agent and landed exactly as the panel
/// lands — `RecordingLanding` for the ops, `ProjectDocument.untitled(around:)`
/// for a new project — so the two doors provably do one thing. This file is
/// the wait around the recorder and the argument vocabulary in front of it;
/// `AgentServer+RecordingResult.swift` is what the answer and the refusals
/// SAY, cut off this file at the 400-line cap, and
/// `AgentServer+RecordingLanding.swift` the landing, cut at camera-recording CR3-0.
///
/// **Runs on the server thread** (`AgentServer.offMainTools`), `import_media`'s
/// shape and never `transcribe`'s synchronous body: the recorder's every
/// callback lands on MAIN, so a main-thread wait would deadlock, and a
/// recording of up to ten minutes is not a thing the UI may freeze for. Every
/// document touch is an `onMain` hop; every wait is a `DispatchSemaphore`
/// signalled from main with an `AgentBox` carrying the answer across.
///
/// **The refusal ORDER is the contract** (`transcribe`'s rule): the caller's
/// own mistakes FIRST, so they stay reachable with no grant — `seconds`
/// missing or outside 1…600, then `source` (its value; the camera's
/// strangers, `camera_layout` and `camera_cutout` among them, spec §11
/// CO-83 (a); for `voice_over`
/// the screen-only arguments given, `keys`, `cursor` and the polish's three
/// among them, then `microphone: false`), `display` with `window`, a `rate` or `size` outside the
/// vocabulary, a `keys` outside its vocabulary (spec §11 CU-62), a `cursor`
/// outside its vocabulary (spec §11 CU-36 (e)), `enhance:
/// true` without a microphone and then with `place: false` (spec §11 AU-69),
/// `auto_zoom`, `shortcut_overlays` and `speed_up_typing` in that order, each
/// with `place: false` and the last two without `keys: "shortcuts"` (road map
/// creator-jobs CU10, spec §11 CU-102 (b)), a `camera_layout` outside its
/// vocabulary and then, with `place: false`, a `camera_layout` given and a
/// `camera_cutout: true` (CO8, spec §11 CO-83 (b)),
/// `microphone: true` (implied by a voice-over) with the Microphone grant
/// absent (the status WORD in the sentence), `keys: "shortcuts"` with the
/// Input Monitoring grant absent (CU-3's sentence, read and never
/// requested), and a `project` naming nothing
/// open, answered by `target(_:)`'s own sentence and never turned into a
/// fresh document. A voice-over stops there: it reads no other grant and
/// looks nothing up (spec §11 recording, "A voice-over is a recording with
/// no picture"). A camera recording (spec §11 CAM-4) then looks the camera
/// up — the named one, else the default, refused naming every camera present
/// — then its format (CAM-6), and only then the Camera grant (`+RecordingCamera.swift`); so
/// does a screen recording given a `camera` to record beside it (spec §11 CAM-10 (5)),
/// before anything screen-side. A
/// screen recording then reads the Screen Recording grant,
/// synchronously, named with the System Settings pane. Only then the
/// display or window lookup, which cannot be asked without the grant — a
/// list with NO display in it (a locked console) is named as that, not as
/// an index out of range. `CGRequestScreenCaptureAccess` and the picker are
/// never called, nor is System Settings opened (decision 4): the panel is
/// where a person grants.
///
/// **The target is `.document(recipeKey:)`**, resolved BEFORE the recording
/// and looked up again AFTER it (`RecordingLanding.resolve`): a document that
/// closed meanwhile lands as a new project and the answer says so, as it does
/// for `place: false` in a new project, which still opens the document.
///
/// **One hook, three waits.** `start` takes `onFinish`, which the recorder
/// calls EXACTLY ONCE at conclude whoever ended the recording — this tool's
/// `stop()`, the menu bar's status item, the system's own indicator
/// (`.userStopped`), a display that slept (`.systemStoppedStream`), a
/// failure — and never for a start that fails, whose error is the start
/// completion's alone. So the waits are: the start's completion (bounded
/// past the recorder's own `armCeiling`, whose timer answers first); the
/// span, a wait on the FINISH semaphore that `onFinish` ends early when
/// something else ended the recording; then, after `stop()`, the same
/// semaphore again, bounded at `stopCeiling(segments:camera:)` over the count
/// the session holds at the stop. `stop()` is sent with NO completion (`onFinish`
/// lands the result once) and in any state past idle JOINS the finishing
/// under way (the recorder's finding 1), so a person's Stop a second before
/// the span ends is a stop that lands, never `.busy`. A stop that never
/// concludes within that bound is a reported timeout naming EVERY movie the
/// recorder still holds — one per segment — and every camera file beside
/// them (`heldCameraPaths`, CAM-10 (7)), and main is asked nothing more:
/// the recorder has no cancel, and the recording may yet finish on its own.
///
/// **A recording this tool starts is controllable from the machine.** Once
/// the start lands it puts up the same `RecorderStatusItem` the panel does
/// (R1 review, R2d): a person at the Mac watching an agent record can pause,
/// resume and stop it from the menu bar — Pause and Resume are the
/// recorder's `pause()` / `resume()`, Stop is `ScreenRecorder.shared.stop()`,
/// which joins — and the item's elapsed label ticks from a 1 Hz timer on
/// main, its mark flipping at once on the recorder's
/// `pauseDidChangeNotification` (`AgentServer+RecordingChrome.swift`, #181).
/// Both come down in `onFinish`, before the landing.
extension AgentServer {

    /// Seconds the tool waits for `stop()` to conclude, INDEPENDENT of
    /// `seconds` and a function of the SEGMENTS the recorder holds: its own
    /// `finishCeiling` (past which it probes whatever is on disk), plus two
    /// sequential `MediaImporter.probe` ceilings of 30 s PER SEGMENT
    /// (`MediaImporter.probeTimeout`; `settle` probes each segment's movie, then
    /// its microphone file — n segments, 2n probes), plus a margin: 75 s
    /// unpaused, 60 s more per further segment. With a `camera` beside the
    /// screen the settle probes a THIRD file per segment, the camera's
    /// (spec §11 CAM-10 (7)): 105 s unpaused, 90 s more per further segment.
    /// The old bound was `seconds + 30`; R2's fixed 75 s was shorter than two
    /// segments' probes.
    static func stopCeiling(segments: Int, camera: Bool = false) -> TimeInterval {
        ScreenRecorder.finishCeiling
            + (camera ? 3 : 2) * MediaImporter.probeTimeout * TimeInterval(max(segments, 1)) + 5
    }

    // MARK: - The tool

    /// `record_screen` — File ▸ New Recording…. The header has the order.
    func recordScreen(_ a: [String: Any]) throws -> String {
        // `importMedia`'s guard: everything below assumes main is free.
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "record_screen must run on the server thread — its name is missing "
                    + "from AgentServer.offMainTools.")
        }

        // 1. The caller's own mistakes, every one before any grant is read.
        let seconds = try recordingSeconds(a)
        let kind = try recordingSourceKind(a)
        let voiceOver = kind == .voiceOver
        let screen = kind == .screen
        let (displayIndex, windowID) = !screen ? (0, nil) : try recordingSourceArguments(a)
        let rate = try intArg(a, "rate") ?? 60
        guard rate == 30 || rate == 60 else {
            throw ToolError(message: "rate must be 30 or 60 (got \(rate)).")
        }
        let resolution = !screen ? .nominal : try recordingResolution(a)
        let microphone = voiceOver ? true : try boolArg(a, "microphone") ?? false
        let systemAudio = !screen ? false : try boolArg(a, "system_audio") ?? true
        let showClicks = !screen ? false : try boolArg(a, "show_clicks") ?? false
        let includeFrameJob =
            !screen ? false : try boolArg(a, "include_framejob_windows") ?? false
        // CU-62: refused by name with voice_over and camera (the screen-only lists).
        let keys =
            !screen ? RecordingKeys.off : try enumArg(a, "keys", RecordingKeys.self) ?? .off
        // CU-36 (e): absent is the source's default (`effectiveCursor`); refused with
        // voice_over and camera by the screen-only lists.
        let cursor = !screen ? nil : try enumArg(a, "cursor", RecordingCursor.self)
        let place = try boolArg(a, "place") ?? true
        // AU-69 (d): after `place`, before any grant.
        let enhance = try recordingEnhance(a, microphone: microphone, place: place)
        // CU-102 (b): the polish on landing, after `enhance`, before any grant.
        let polish = try recordingPolish(a, place: place, keys: keys)
        // CO-83 (b): the camera's layout and cutout, after the polish, before any grant.
        let cameraLanding = try recordingCameraLanding(a, place: place)
        let folder = try recordingFolder(a)
        if microphone {
            let status = RecordingGrant.microphoneStatus
            guard status == .authorized else {
                throw ToolError(message: RecordingGrant.microphoneRefusal(status))
            }
        }
        if keys == .shortcuts, !RecordingGrant.inputMonitoringGranted {
            throw ToolError(message: RecordingGrant.inputMonitoringRefusal)
        }
        // A misspelt `project` is the caller's mistake too — answered above
        // the grant, where `transcribe` answers its own id refusals.
        let destination = try onMain { try self.recordingDestination(a) }

        // A voice-over has no picture: no grant but the Microphone's is
        // read, and there is nothing to look up.
        var source = RecordingSource.voiceOver
        var filter: SCContentFilter?
        var cameraPick: CameraPick?
        // CAM-10 (5): a screen recording given a `camera` records it beside the screen.
        let cameraBeside = try kind == .screen && recordingCameraArgument(a) != nil
        if kind == .camera || cameraBeside {
            // CAM-3 (7) and (8): the camera lookup and its format, then the Camera grant —
            // read, never requested; for a camera beside the screen, before its grant.
            cameraPick = try recordingCamera(a)
        }
        if kind == .camera { source = .camera }
        if kind == .screen {
            // 2. The Screen Recording grant — read, never requested.
            guard RecordingGrant.screenRecordingGranted else {
                throw ToolError(message: RecordingGrant.screenRecordingRefusal)
            }

            // 3. The content (unlistable without the grant) and the
            //    programmatic filter — a display source excludes Frame Job
            //    unless `include_framejob_windows`; the tool excludes no
            //    window.
            let content = try shareableContent()
            source = try recordingSource(displayIndex, windowID, in: content)
            do {
                filter = try ScreenRecorder.filter(
                    for: source, in: content,
                    excluding: RecordingExclusion.make(
                        includeFrameJobWindows: includeFrameJob,
                        ownBundleID: Bundle.main.bundleIdentifier, panelWindowID: nil))
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
        }

        // 4. The choice; the microphone is the DEFAULT audio device.
        var microphoneID: String?
        if microphone {
            guard let device = AVCaptureDevice.default(for: .audio) else {
                throw ToolError(message: "No microphone is available.")
            }
            microphoneID = device.uniqueID
        }
        let choice = RecordingChoice(
            source: source, includeFrameJobWindows: includeFrameJob,
            microphone: microphoneID, systemAudio: systemAudio,
            showClicks: showClicks, rate: rate, resolution: resolution,
            destination: destination, folder: folder ?? RecordingFiles.folder(),
            camera: cameraPick?.id, cameraFormat: cameraPick?.format, enhanceMicrophone: enhance,
            keys: keys, cursor: cursor, autoZoom: polish.contains(.autoZoom),
            shortcutOverlays: polish.contains(.shortcutOverlays),
            speedUpTyping: polish.contains(.speedUpTyping), cameraLayout: cameraLanding.layout,
            cameraCutout: cameraLanding.cutout)

        // 5. The recording: start, the span, stop — all waits on this thread.
        let result = try record(
            filter: filter, choice: choice, seconds: seconds, cameraBeside: cameraBeside)

        // 6. A drag in the target document is waited out HERE, on this
        //    thread — a wait on main would hold the gesture it waits for.
        awaitGestureEnd(destination)

        // 7. The landing, on main, through the door the panel does not use;
        //    then, with `enhance`, Enhance Voice as its own step (AU-68 (f)),
        //    then the polish, each command its own step (CU-101 (j)).
        return try landAndEnhance(result, place: place)
    }

    // MARK: - The recording

    /// Start, the span, stop. See the header for the hook and the waits. A
    /// filter is a screen recording, started through `start`; with none, a
    /// camera (`choice.source == .camera`) is started through `startCamera`
    /// and a voice-over through `startVoiceOver`, and the span waits first
    /// for their first segment's start (`awaitFirstStart`). `cameraBeside`
    /// sizes the stop wait for the camera's probe (CAM-10 (7)).
    private func record(
        filter: SCContentFilter?, choice: RecordingChoice, seconds: Double, cameraBeside: Bool
    ) throws -> RecordingResult {
        let recorder = ScreenRecorder.shared
        let started = DispatchSemaphore(value: 0)
        let startBox = AgentBox<Result<Void, Error>>()
        let finished = DispatchSemaphore(value: 0)
        let box = AgentBox<Result<RecordingResult, Error>>()
        let chrome = RecordingToolChrome()
        // `onFinish` runs on MAIN, once: the status item comes down before
        // the landing, and the box is written before the signal.
        let deliver: (Result<RecordingResult, Error>) -> Void = { outcome in
            chrome.remove()
            if box.value == nil { box.value = outcome }
            finished.signal()
        }
        let startCompletion: (Error?) -> Void = { error in
            startBox.value = error.map { .failure($0) } ?? .success(())
            started.signal()
        }
        onMain {
            if let filter {
                recorder.start(
                    filter: filter, choice: choice, mayAsk: false, onFinish: deliver,
                    completion: startCompletion)
            } else if choice.source == .camera {
                recorder.startCamera(
                    choice: choice, mayAsk: false, onFinish: deliver,
                    completion: startCompletion)
            } else {
                recorder.startVoiceOver(
                    choice: choice, mayAsk: false, onFinish: deliver,
                    completion: startCompletion)
            }
        }
        // The recorder's own arm timer answers first; this bound is for a
        // start that never answers at all.
        guard started.wait(timeout: .now() + ScreenRecorder.armCeiling + 5) == .success else {
            throw ToolError(
                message: "record_screen timed out waiting for the recording to start."
                    + Self.recordingAlertClause)
        }
        if case .failure(let error) = startBox.value ?? .success(()) {
            throw ToolError(message: Self.startSentence(of: error))
        }
        onMain { chrome.show(recorder) }
        if filter == nil { awaitFirstStart(recorder, ended: box) }

        // The span: the recording runs on main's run loop, this thread waits,
        // and only `onFinish` — an external stop, a failure — wakes it early.
        if finished.wait(timeout: .now() + seconds) == .timedOut {
            // The segment count is read in the SAME hop that stops: a Resume
            // landing between the two would mint a segment — two probes — the
            // wait had not budgeted for. The item freezes first (its doc).
            let segments = onMain { () -> Int in
                chrome.freeze()
                let count = max(recorder.heldSegmentCount, 1)
                recorder.stop()
                return count
            }
            let ceiling = Self.stopCeiling(segments: segments, camera: cameraBeside)
            guard finished.wait(timeout: .now() + ceiling) == .success else {
                // The files the recorder still holds — one per segment, and
                // a camera file beside each movie that has one.
                var cameras: [String] = []
                let movies = onMain { () -> [String] in
                    chrome.remove()
                    cameras = recorder.heldCameraPaths
                    return recorder.heldFilePaths
                }
                throw ToolError(
                    message: Self.finishTimeoutSentence(
                        movies: movies, cameras: cameras, camera: cameraBeside,
                        voiceOver: choice.source == .voiceOver))
            }
        }
        guard let outcome = box.value else {
            throw ToolError(message: "The recording ended without a result.")
        }
        do {
            return try outcome.get()
        } catch {
            throw ToolError(message: Self.sentence(of: error))
        }
    }

    /// SERVER THREAD. A voice-over's start completion answers BEFORE its
    /// writer's did-start, so a span counted from it comes out short by the
    /// input's start-up time (a second on a Bluetooth input); a camera's
    /// answers when segment 0's writer is armed, before its first buffer
    /// (CAM-4 point 5: the span is the picture recorded, the warm-up not in
    /// it). This polls `heldFirstStartedAt` through `onMain` until it lands,
    /// the recording has already ended (`ended` written by `onFinish`), or
    /// `ScreenRecorder.armCeiling` passes — past which the span runs as
    /// before. A screen recording's start already answers after its arm.
    private func awaitFirstStart(
        _ recorder: ScreenRecorder, ended: AgentBox<Result<RecordingResult, Error>>
    ) {
        let deadline = Date().addingTimeInterval(ScreenRecorder.armCeiling)
        while Date() < deadline {
            let waiting = onMain { recorder.heldFirstStartedAt == nil && ended.value == nil }
            guard waiting else { return }
            Thread.sleep(forTimeInterval: 0.02)
        }
    }
}
import AVFoundation
import AppKit
import ScreenCaptureKit

/// `record_screen`'s ARGUMENT vocabulary and the lookup the arguments meet —
/// the second cut off `AgentServer+Recording.swift` (R1 review; the first is
/// `+RecordingResult.swift`), taken when the fixes put that file at 481
/// lines against the 400-line cap for a new file. The seam is the sentence
/// its header had used to describe itself: "the wait around the recorder
/// and the argument vocabulary in front of it" — the wait stayed, the
/// vocabulary came here, and with it the shareable-content call and the
/// display ordering, because they are what the `display` and `window`
/// arguments RESOLVE against and nothing else reads them. Every function is
/// pure in the arguments, or a wait on one framework answer; none touches
/// the recorder. `private` → internal is the whole cost.
///
/// **The refusal ORDER is decided in the caller**, `recordScreen`, which
/// calls these in the order the header there fixes: the caller's own
/// mistakes, the grant, the lookup. Nothing here reads a grant.
extension AgentServer {

    // MARK: - The arguments

    /// `source`: what is recorded — the screen (the default), the
    /// microphone alone (the panel's Microphone Only, spec §11 recording) or
    /// a camera alone (spec §11 CAM-4, `+RecordingCamera.swift`).
    enum RecordingSourceKind: String, CaseIterable {
        case screen
        case voiceOver = "voice_over"
        case camera
    }

    /// The arguments a voice-over refuses by name: everything that only a
    /// picture or the stream reads.
    static let voiceOverScreenOnlyArguments = [
        "display", "window", "system_audio", "show_clicks", "size", "include_framejob_windows",
        "auto_zoom", "shortcut_overlays", "speed_up_typing",
        "keys", "cursor",
    ]

    /// `source`, default `screen`; an unknown value refused with the
    /// vocabulary; then the camera's argument checks (CAM-4: `camera` with
    /// another source, a camera's own strangers). For `voice_over`, the
    /// screen-only arguments the caller
    /// GAVE (a JSON null is not given, `scalarArg`'s rule) are refused
    /// together, in `voiceOverScreenOnlyArguments` order, then
    /// `microphone: false`.
    func recordingSourceKind(_ a: [String: Any]) throws -> RecordingSourceKind {
        let kind = try enumArg(a, "source", RecordingSourceKind.self) ?? .screen
        try recordingCameraStrangers(a, kind: kind)
        guard kind == .voiceOver else { return kind }
        let strangers = Self.voiceOverScreenOnlyArguments.filter { a[$0] != nil && !(a[$0] is NSNull) }
        guard strangers.isEmpty else {
            throw ToolError(
                message: "With source voice_over, " + strangers.joined(separator: ", ")
                    + " cannot be given — a voice-over records the microphone alone.")
        }
        if try boolArg(a, "microphone") == false {
            throw ToolError(
                message: "With source voice_over, microphone cannot be false — a voice-over "
                    + "records the microphone alone.")
        }
        return kind
    }

    /// `seconds`: required, 1…600. Spelled back as the caller sent it (`0`,
    /// not `0.0`) when it is whole.
    func recordingSeconds(_ a: [String: Any]) throws -> Double {
        guard let seconds = try doubleArg(a, "seconds") else {
            throw ToolError(message: "Missing required argument: seconds")
        }
        guard seconds >= 1, seconds <= 600 else {
            let whole = seconds == seconds.rounded() && abs(seconds) < 1e15
            let spelled = whole ? String(Int(seconds)) : String(seconds)
            throw ToolError(message: "seconds must be 1…600 (got \(spelled)).")
        }
        return seconds
    }

    /// `display` (an index, default 0) and `window` (a CGWindowID), at most
    /// one; the index meets the LIST later, once it can be asked for.
    func recordingSourceArguments(_ a: [String: Any]) throws -> (Int, CGWindowID?) {
        let display = try intArg(a, "display")
        let window = try intArg(a, "window")
        guard display == nil || window == nil else {
            throw ToolError(
                message: "Pass display or window, not both — a recording is of one or the other.")
        }
        if let display, display < 0 {
            throw ToolError(message: "display must be 0 or more (got \(display)).")
        }
        var windowID: CGWindowID?
        if let window {
            guard window >= 0, window <= Int(CGWindowID.max) else {
                throw ToolError(message: "window must be a CGWindowID (got \(window)).")
            }
            windowID = CGWindowID(window)
        }
        return (display ?? 0, windowID)
    }

    /// `enhance` (spec §11 AU-69 (d)), default false: true needs a microphone,
    /// then a clip to enhance — `place` — refused in that order.
    func recordingEnhance(_ a: [String: Any], microphone: Bool, place: Bool) throws -> Bool {
        guard try boolArg(a, "enhance") ?? false else { return false }
        guard microphone else {
            throw ToolError(
                message: "enhance: true enhances the microphone's clip, so it needs "
                    + "microphone: true (or source voice_over).")
        }
        guard place else {
            throw ToolError(
                message: "enhance: true needs place: true — with place: false the microphone "
                    + "lands as media with no clip to enhance.")
        }
        return true
    }

    /// `size`: `nominal` (default) or `best`, `requestedFrameFormat`'s form.
    func recordingResolution(_ a: [String: Any]) throws -> RecordingResolution {
        try enumArg(a, "size", RecordingResolution.self, folding: true) ?? .nominal
    }

    /// `path`, the FOLDER: trimmed, tilde-expanded, and an empty or blank
    /// string counting as absent — `RecordingFiles.folder()` then applies —
    /// because `URL(fileURLWithPath: "")` is the process's working directory,
    /// and a recording written into whatever `cwd` the app was launched
    /// from is a file nobody can find.
    func recordingFolder(_ a: [String: Any]) throws -> URL? {
        guard let raw = try stringArg(a, "path") else { return nil }
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        return URL(
            fileURLWithPath: (trimmed as NSString).expandingTildeInPath, isDirectory: true)
    }

    /// Where the recording will land, decided BEFORE it starts. A named
    /// `project` goes through `target(_:)` and its refusal stands; no name
    /// and no document is `.newProject`; otherwise the frontmost. Main.
    func recordingDestination(_ a: [String: Any]) throws -> RecordingDestination {
        if try stringArg(a, "project") != nil {
            return .document(recipeKey: try target(a).recipeKey)
        }
        if openProjects().isEmpty { return .newProject }
        return .document(recipeKey: try target(a).recipeKey)
    }

    // MARK: - The content

    /// `ScreenRecorder.shareableContent`, CALLED from this thread (the helper
    /// issues the framework call from a global queue and hops the completion
    /// to main whatever thread asks) and waited for here. Not through
    /// `onMain`: on a locked console the framework held the calling thread
    /// ~37 s before answering nothing — main's, through a hop.
    func shareableContent() throws -> SCShareableContent {
        let semaphore = DispatchSemaphore(value: 0)
        let box = AgentBox<Result<SCShareableContent, Error>>()
        ScreenRecorder.shareableContent { outcome in
            box.value = outcome
            semaphore.signal()
        }
        guard semaphore.wait(timeout: .now() + 20) == .success else {
            throw ToolError(message: "Timed out listing the shareable displays and windows.")
        }
        switch box.value {
        case .success(let content): return content
        case .failure(let error): throw ToolError(message: error.localizedDescription)
        case nil:
            throw ToolError(message: "The shareable displays and windows could not be listed.")
        }
    }

    /// The shareable displays, MAIN first — so `display` 0 means what the
    /// catalog says whatever order the framework lists them in.
    static func orderedDisplays(_ content: SCShareableContent) -> [SCDisplay] {
        let main = CGMainDisplayID()
        return content.displays.filter { $0.displayID == main }
            + content.displays.filter { $0.displayID != main }
    }

    /// The source the two arguments name. A window id naming nothing
    /// shareable is refused by `ScreenRecorder.filter(for:in:excluding:)`'s sentence.
    /// An EMPTY display list is a fact about the host — the console is
    /// locked or every display is asleep (measured: a true preflight and
    /// zero displays, the night the proof was written) — and is named as
    /// that, BEFORE the range sentence, which would otherwise read
    /// "display must be 0…0 (got 0)" for a caller who asked for nothing odd.
    func recordingSource(
        _ displayIndex: Int, _ windowID: CGWindowID?, in content: SCShareableContent
    ) throws -> RecordingSource {
        if let windowID { return .window(windowID) }
        let displays = Self.orderedDisplays(content)
        guard !displays.isEmpty else {
            throw ToolError(
                message: "No display is shareable right now — the console is locked or every "
                    + "display is asleep; nothing can be recorded until one is.")
        }
        guard displayIndex < displays.count else {
            throw ToolError(
                message: "display must be 0…\(displays.count - 1) (got \(displayIndex)); "
                    + "\(displays.count) display\(displays.count == 1 ? " is" : "s are") "
                    + "shareable.")
        }
        return .display(displays[displayIndex].displayID)
    }
}

// app/Sources/ProjectDocument+Recording.swift — a recording as a new
// document (road map 3, phase R1b, the `.newProject` landing; a sequence of
// segments since R2b).
//
// An `extension ProjectDocument` in its own file, `+DisplayStem`'s shape: the
// base file is far over the ~600-line cap and takes no code it does not have
// to. What it HAD to take is `adoptImported(_:source:fps:)` — `project` and
// `importSourceURL` are `private(set)` and `clampViewState()` is private, so
// an extension in another file cannot build the untitled document itself —
// and that method is `readMediaFile`'s post-probe body moved whole, so a
// recording becomes a document by the ONE spelling File ▸ Open uses for a
// movie (road map 3, decision 1: a recording is ordinary media).

import AppKit

extension ProjectDocument {
    /// The untitled, dirty document a finished recording opens as — spec
    /// §1's opening flow for a movie, with two differences the recorder
    /// asks for. The CANVAS takes the recorder's rate (`choice.rate`, 30 or
    /// 60 — the grid the person chose) while the media record keeps the
    /// file's own, which for a ScreenCaptureKit file is whatever the screen
    /// did (R0 measured 25.58 fps at a 1/60 interval; decision 3). And the
    /// REMAINDER — a paused recording's later segments, back to back on the
    /// first one's track, and every microphone file on a new back track —
    /// lands through `RecordingLanding.remainderPlacement` as ONE grouped
    /// edit; the FIRST segment is what the document IS.
    ///
    /// **The order is a contract**, measured on the real class by the
    /// document scout and once more by the review, and each step leans on
    /// the one before:
    ///
    /// 1. `openUntitledDocumentAndDisplay(false)` — the controller ADDS the
    ///    document itself (no `addDocument`, or it is listed twice) and,
    ///    with `false`, makes no window yet.
    /// 2. `adoptImported` — with the first segment's descriptor, and BEFORE
    ///    anything reads `displayName`: AppKit pins the name on its first
    ///    read, and the name is `defaultDraftName()`, which is the
    ///    recording's stem only once `importSourceURL` is set. Nothing
    ///    between 1 and 2 logs, summarises or shows the document.
    /// 3. **The import count** — `fileModificationDate = nil` and
    ///    `countEditChange(.changeDone)`, the two lines `makeWindowControllers`
    ///    runs for an opened movie (`ProjectDocument.swift`, under its
    ///    `importSourceURL != nil, fileURL == nil, !isDocumentEdited` guard)
    ///    — run HERE, before the remainder's edit and with or without one.
    ///    The position is the fix for a defect the review measured on the
    ///    change count: counted the other way round, the remainder's edit
    ///    dirtied the document first, `makeWindowControllers`' guard found
    ///    it edited and skipped its own count, and ONE ⌘Z brought the count
    ///    back to zero — a recording's document that read CLEAN, which ⌘W
    ///    then closed without asking. Counted first, the remainder's edit
    ///    stacks a SECOND count and its undo leaves the first standing, so
    ///    the document is dirty with the remainder or without it, as an
    ///    opened movie is. Without a remainder this is the same one count
    ///    `makeWindowControllers` would have made, one step earlier.
    /// 4. The remainder's grouped edit — named by
    ///    `RecordingLanding.remainderActionName(for:)`: "Add Microphone"
    ///    for one segment with any voice — its own or a left-out segment's
    ///    (#181 item 2) — "Add Camera and Microphone" or "Add Camera" for
    ///    one segment with a camera beside the screen, with a voice or
    ///    without (spec §11 CAM-10 (4)), "Add Recording Segments" otherwise,
    ///    and NOT "Add Recording", because the step removes the remainder
    ///    and keeps the first segment's picture, and the Edit menu should
    ///    say what ⌘Z will do — before the window, so the `generateCaches()`
    ///    inside `makeWindowControllers` covers EVERY file and the editor's
    ///    first composition is built once, over the finished project, rather
    ///    than rebuilt when the later clips land. Every op was trialled
    ///    purely by `remainderPlacement`, so the windowless commit cannot
    ///    reach `presentError`'s app-modal arm.
    /// 5. `makeWindowControllers()` — its own import count is guarded out by
    ///    step 3 (the guard counts only a document nothing has counted, which
    ///    is what makes the two orders equivalent for a movie and step 3
    ///    safe here); what it still does is run `generateCaches()` and
    ///    `ensureReversedMedia()` and add the editor window.
    /// 6. `showWindows()`.
    ///
    /// A throw after step 1 CLOSES the document it opened, or a failed
    /// landing would leave an invisible untitled draft in the controller
    /// with a blank project in it.
    ///
    /// **Answers the document AND the remainder's `notes`** — the sentences
    /// `remainderPlacement` wrote for each file it landed as media with no
    /// clip (a voice too short for a frame, a voice wholly under the previous
    /// one, or everything behind a first picture the core refused), each
    /// naming the file. A document cannot show a note, and a landing that
    /// swallowed them would leave a person looking for a voice that is in the
    /// Media tab and nowhere on the timeline; the panel's note and the tool's
    /// `note` field append them. Empty when everything landed, and always
    /// empty with no remainder. A tuple rather than a property on the
    /// document because the notes are about ONE landing, not about the
    /// document, and the two callers read them exactly once.
    ///
    /// Two limits, recorded. With one segment and no microphone the document
    /// has NO undo step — its first project is what the document is, as for
    /// an opened movie — while with a remainder, ⌘Z (Undo Add Microphone, or
    /// Undo Add Recording Segments) removes the remainder's media and clips
    /// and leaves the first picture, and the document STAYS dirty under it
    /// (step 3's count): the first segment is the document, the rest is an
    /// edit to it. And every file stays on disk on either undo, as undoing
    /// Add Media… leaves the file (road map 3 §0). Main thread.
    static func untitled(around result: RecordingResult) throws
        -> (document: ProjectDocument, notes: [String])
    {
        assert(Thread.isMainThread)
        let controller = NSDocumentController.shared
        guard let document = try controller.openUntitledDocumentAndDisplay(false)
            as? ProjectDocument
        else {
            throw ReelCoreError(
                message: "The untitled document did not open as a Frame Job project.")
        }
        var notes: [String] = []
        do {
            try document.adoptImported(
                result.descriptor, source: URL(fileURLWithPath: result.descriptor.path),
                fps: Fps(num: result.choice.rate, den: 1))
            // Step 3: the import count, BEFORE the remainder's edit — see the
            // doc comment for why the order is the fix.
            document.fileModificationDate = nil
            document.countEditChange(.changeDone)
            if let remainder = try RecordingLanding.remainderPlacement(result, in: document) {
                document.performGroupedEdit(
                    RecordingLanding.remainderActionName(for: result), remainder.ops)
                notes = remainder.notes
            }
        } catch {
            document.close()
            throw error
        }
        document.makeWindowControllers()
        document.showWindows()
        return (document, notes)
    }
}
